impl Theme {
    pub fn current(cx: &gpui_kit::App) -> Self {
        cx.try_global::<CurrentTheme>()
            .map(|theme| theme.0)
            .unwrap_or_else(Self::dark)
    }
    pub fn dark() -> Self {
        Self {
            mode: Mode::Dark,
            canvas: rgb(0x141419),
            backdrop: rgba(0x08070a94), // rgba(8,7,10,.58)
            media_canvas: rgb(0x090a0c),
            media_surface: rgb(0x000000),
            media_chrome: rgba(0x141419cc),        // rgba(20,20,25,.8)
            media_chrome_raised: rgba(0x141419d6), // rgba(20,20,25,.84)
            sidebar: rgb(0x202027),
            surface: rgb(0x18181e),
            surface_raised: rgb(0x292932),
            message_hover: rgb(0x22222b),
            surface_interactive: rgb(0x3b3b48),
            surface_selected: rgb(0x45455a),
            text: rgb(0xeeeaf1),
            text_muted: rgb(0xb8b3c1),
            accent: rgb(0x9fa5ee),
            link: rgb(0xb7bdfc),
            focus: rgb(0xb7bdfc),
            accent_text: rgb(0x202343),
            success: rgb(0xa8dba8),
            success_text: rgb(0xa8dba8),
            warning: rgb(0xf3cb8e),
            danger: rgb(0xffb4ab),
            danger_text: rgb(0x202343),
            outline: rgba(0xffffff29),        // rgba(255,255,255,.16)
            accent_outline: rgba(0xaeb3f12e), // rgba(174,179,241,.18)
            qr_backdrop: rgb(0xffffff),
            focus_ring: rgba(0x9fa5ee59), // rgba(159,165,238,.35)
            radius_sm: 9.0,
            radius_md: 12.0,
            radius_lg: 16.0,
            radius_pill: 999.0,
            space1: 4.0,
            space2: 8.0,
            space3: 12.0,
            space4: 16.0,
            space5: 20.0,
            space6: 24.0,
            font_size_xs: 11.0,
            font_size_sm: 12.0,
            font_size_md: 14.0,
            font_size_lg: 16.0,
            font_size_xl: 20.0,
            line_height_compact: 1.2,
            line_height_normal: 1.45,
            shadow_sm: ShadowSpec {
                dy: 2.0,
                blur: 8.0,
                color: rgba(0x00000033),
            },
            shadow_md: ShadowSpec {
                dy: 12.0,
                blur: 32.0,
                color: rgba(0x00000052),
            },
            shadow_floating: ShadowSpec {
                dy: 10.0,
                blur: 28.0,
                color: rgba(0x00000076),
            },
            shadow_viewer: ShadowSpec {
                dy: 24.0,
                blur: 80.0,
                color: rgba(0x0000008c),
            },
            shadow_pip: ShadowSpec {
                dy: 18.0,
                blur: 52.0,
                color: rgba(0x00000085),
            },
            duration_fast: Duration::from_millis(150),
            duration_normal: Duration::from_millis(220),
            easing_standard: [0.2, 0.8, 0.2, 1.0],
        }
    }

    pub fn light() -> Self {
        // The light theme only overrides the tokens listed in
        // `themes.stylex.ts`; media surfaces, backdrop and accent outline
        // intentionally inherit the dark values.
        let mut t = Self::dark();
        t.mode = Mode::Light;
        t.canvas = rgb(0xfaf4ed);
        t.sidebar = rgb(0xf7f1eb);
        t.surface = rgb(0xfaf4ed);
        t.surface_raised = rgb(0xfffaf3);
        t.message_hover = rgb(0xf2ebe4);
        t.surface_interactive = rgb(0xf2e9e1);
        t.surface_selected = rgb(0xeee7ef);
        t.text = rgb(0x575279);
        t.text_muted = rgb(0x67617a);
        t.accent = rgb(0x907aa9);
        t.link = rgb(0x695480);
        t.focus = rgb(0x695480);
        t.accent_text = rgb(0x211b2a);
        t.success = rgb(0x3b8b65);
        t.success_text = rgb(0x28694b);
        t.warning = rgb(0x9b681f);
        t.danger = rgb(0xa6383e);
        t.danger_text = rgb(0xffffff);
        t.outline = rgb(0xe5deda);
        t.focus_ring = rgba(0x907aa940); // rgba(144,122,169,.25)
        t.shadow_sm = ShadowSpec {
            dy: 2.0,
            blur: 8.0,
            color: rgba(0x5752790f),
        };
        t.shadow_md = ShadowSpec {
            dy: 12.0,
            blur: 32.0,
            color: rgba(0x5752791a),
        };
        t
    }

    /// Apply a user accent exactly as `accentPalette` in `src/design/accent.ts`:
    /// selection mix, contrast-picked accent text, legibility-walked link.
    pub fn with_accent(mut self, value: &str) -> Self {
        let Some(palette) = accent_palette(
            value,
            self.mode,
            rgb8(self.surface),
            rgb8(self.surface_interactive),
        ) else {
            return self;
        };
        self.accent = rgba_u8(palette.accent, 255);
        self.accent_text = rgba_u8(palette.accent_text, 255);
        self.link = rgba_u8(palette.link, 255);
        self.focus = self.link;
        self.surface_selected = rgba_u8(palette.selection, 255);
        self.focus_ring = rgba_u8(palette.link, 64); // `${hex(link)}40`
        self
    }
}

pub fn rgb8(color: Rgba) -> Rgb8 {
    [
        (color.r * 255.0).round() as u8,
        (color.g * 255.0).round() as u8,
        (color.b * 255.0).round() as u8,
    ]
}

/// Channel-wise sRGB mix, equivalent to CSS `color-mix(in srgb, a, b amount)`.
/// Used for hover overlays and derived surfaces (e.g. `dangerSubtle`).
pub fn mix_color(a: Rgba, b: Rgba, amount: f32) -> Rgba {
    let channel = |x: f32, y: f32| x * (1.0 - amount) + y * amount;
    Rgba {
        r: channel(a.r, b.r),
        g: channel(a.g, b.g),
        b: channel(a.b, b.b),
        a: channel(a.a, b.a),
    }
}

/// Tint overlay for hover/active feedback: on an opaque surface this is a
/// 10%/18% mix toward the text color; on a transparent surface it is the
/// text color at that alpha. Mirrors `buttonInteraction` in `src/ui`.
pub fn feedback_overlay(base: Rgba, text: Rgba, amount: f32) -> Rgba {
    if base.a >= 1.0 {
        mix_color(base, Rgba { a: 1.0, ..text }, amount)
    } else {
        Rgba { a: amount, ..text }
    }
}

fn rgba_u8([r, g, b]: Rgb8, a: u8) -> Rgba {
    Rgba {
        r: r as f32 / 255.0,
        g: g as f32 / 255.0,
        b: b as f32 / 255.0,
        a: a as f32 / 255.0,
    }
}

#[cfg(test)]
fn hex8([r, g, b]: Rgb8) -> String {
    format!("#{r:02x}{g:02x}{b:02x}")
}

// --- Accent derivation (port of src/design/accent.ts) ---

pub struct AccentPalette {
    pub accent: Rgb8,
    pub accent_text: Rgb8,
    pub link: Rgb8,
    pub selection: Rgb8,
}

fn mix(a: Rgb8, b: Rgb8, amount: f64) -> Rgb8 {
    let channel = |i: usize| (a[i] as f64 * (1.0 - amount) + b[i] as f64 * amount).round() as u8;
    [channel(0), channel(1), channel(2)]
}

fn luminance(color: Rgb8) -> f64 {
    color
        .iter()
        .map(|&value| {
            let channel = value as f64 / 255.0;
            if channel <= 0.04045 {
                channel / 12.92
            } else {
                ((channel + 0.055) / 1.055).powf(2.4)
            }
        })
        .zip([0.2126, 0.7152, 0.0722])
        .map(|(value, weight)| value * weight)
        .sum()
}

fn contrast_ratio(a: Rgb8, b: Rgb8) -> f64 {
    let (la, lb) = (luminance(a), luminance(b));
    (la.max(lb) + 0.05) / (la.min(lb) + 0.05)
}

pub fn accent_palette(
    value: &str,
    mode: Mode,
    surface: Rgb8,
    interactive: Rgb8,
) -> Option<AccentPalette> {
    let hex = value.strip_prefix('#')?;
    if hex.len() != 6 || !hex.bytes().all(|b| b.is_ascii_hexdigit()) {
        return None;
    }
    let accent: Rgb8 =
        [0, 2, 4].map(|offset| u8::from_str_radix(&hex[offset..offset + 2], 16).unwrap());
    let (black, white): (Rgb8, Rgb8) = ([0, 0, 0], [255, 255, 255]);
    let selection = mix(
        surface,
        accent,
        if mode == Mode::Light { 0.07 } else { 0.18 },
    );
    let accent_text = if contrast_ratio(accent, white) >= contrast_ratio(accent, black) {
        white
    } else {
        black
    };
    // Preserve the hue where possible, but links/focus must remain legible
    // even when the accent itself is white, black, or a very pale pastel.
    let mut link = accent;
    for step in 0..=100 {
        link = mix(
            accent,
            if mode == Mode::Light { black } else { white },
            step as f64 / 100.0,
        );
        if [surface, interactive, selection]
            .iter()
            .all(|&background| contrast_ratio(link, background) >= 4.5)
        {
            break;
        }
    }
    Some(AccentPalette {
        accent,
        accent_text,
        link,
        selection,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    // Expected values generated by running the original
    // `src/design/accent.ts` under node (ground truth).
    const DARK_SURFACE: Rgb8 = [0x18, 0x18, 0x1e];
    const DARK_INTERACTIVE: Rgb8 = [0x3b, 0x3b, 0x48];
    const LIGHT_SURFACE: Rgb8 = [0xfa, 0xf4, 0xed];
    const LIGHT_INTERACTIVE: Rgb8 = [0xf2, 0xe9, 0xe1];

    #[test]
    fn dark_default_accent_matches_typescript() {
        let p = accent_palette("#9fa5ee", Mode::Dark, DARK_SURFACE, DARK_INTERACTIVE).unwrap();
        assert_eq!(hex8(p.accent), "#9fa5ee");
        assert_eq!(hex8(p.accent_text), "#000000");
        assert_eq!(hex8(p.link), "#9fa5ee");
        assert_eq!(hex8(p.selection), "#303143");
    }

    #[test]
    fn light_default_accent_matches_typescript() {
        let p = accent_palette("#907aa9", Mode::Light, LIGHT_SURFACE, LIGHT_INTERACTIVE).unwrap();
        assert_eq!(hex8(p.accent), "#907aa9");
        assert_eq!(hex8(p.accent_text), "#000000");
        assert_eq!(hex8(p.link), "#736287");
        assert_eq!(hex8(p.selection), "#f3ebe8");
    }

    #[test]
    fn white_accent_stays_legible() {
        let p = accent_palette("#ffffff", Mode::Dark, DARK_SURFACE, DARK_INTERACTIVE).unwrap();
        assert_eq!(hex8(p.accent_text), "#000000");
        assert_eq!(hex8(p.link), "#ffffff");
        assert_eq!(hex8(p.selection), "#424247");
    }

    #[test]
    fn invalid_values_are_rejected() {
        assert!(accent_palette("red", Mode::Dark, DARK_SURFACE, DARK_INTERACTIVE).is_none());
        assert!(accent_palette("#fff", Mode::Dark, DARK_SURFACE, DARK_INTERACTIVE).is_none());
        assert!(accent_palette("#gggggg", Mode::Dark, DARK_SURFACE, DARK_INTERACTIVE).is_none());
    }

    #[test]
    fn light_theme_keeps_media_surfaces_dark() {
        let light = Theme::light();
        assert_eq!(rgb8(light.media_canvas), [0x09, 0x0a, 0x0c]);
        assert_eq!(rgb8(light.canvas), [0xfa, 0xf4, 0xed]);
    }

    #[test]
    fn with_accent_applies_derived_palette() {
        let theme = Theme::dark().with_accent("#9fa5ee");
        assert_eq!(rgb8(theme.surface_selected), [0x30, 0x31, 0x43]);
        assert_eq!(rgb8(theme.link), [0x9f, 0xa5, 0xee]);
    }
}
